 5	/// AD-4 — the one place retry policy lives. Retries only the 6 server
 6	/// `retryable:true` codes (`error-taxonomy.md`); every other failure
 7	/// (including the local `MalformedResponse`) surfaces once, unretried.
 8	///
 9	/// Design note (docs/input is silent on the schedule): fixed 500ms delay,
10	/// max 2 retries.
11	class RetryInterceptor extends Interceptor {
12	  RetryInterceptor(this._dio);
13	
14	  final Dio _dio;
15	
16	  /// The 6 server `retryable:true` codes — the only codes this interceptor
17	  /// ever retries.
18	  static const Set<String> retryableCodes = {
19	    'NETWORK_TIMEOUT',
20	    'NETWORK_OFFLINE',
21	    'PII_CHECK_FAILED',
22	    'EMBEDDING_FAILED',
23	    'AI_GENERATION_TIMEOUT',
24	    'RATE_LIMITED',
25	  };
26	
27	  static const int maxRetries = 2;
28	  static const Duration retryDelay = Duration(milliseconds: 500);
29	
30	  static const _attemptKey = 'cerne_retry_attempt';
31	
32	  @override
33	  void onError(DioException err, ErrorInterceptorHandler handler) async {
34	    final attempt = attemptOf(err);
35	
36	    if (shouldRetry(err, attempt)) {
37	      await Future<void>.delayed(retryDelay);
38	      final options = err.requestOptions;
39	      options.extra[_attemptKey] = attempt + 1;
40	      try {
41	        final response = await _dio.fetch<dynamic>(options);
42	        handler.resolve(response);
43	      } on DioException catch (retryError) {
44	        handler.next(retryError);
45	      } catch (retryError) {
46	        // Any non-DioException thrown by the retried fetch must still reach
47	        // the caller through `handler`, never escape unhandled (RNF09).
48	        handler.next(
49	          DioException(
50	            requestOptions: options,
51	            error: retryError,
52	            type: DioExceptionType.unknown,
53	          ),
54	        );
55	      }
56	      return;
57	    }
58	
59	    handler.next(err);
60	  }
61	
62	  /// How many retries have already been attempted for this request.
63	  static int attemptOf(DioException err) =>
64	      (err.requestOptions.extra[_attemptKey] as int?) ?? 0;
65	
66	  /// The backend error `code` for [err] — delegates to the shared
67	  /// [dioErrorCodeOf] (also used by `ApiClient`) so a client-side timeout or
68	  /// a cancelled request is never misread as `NETWORK_OFFLINE` here.
69	  static String? errorCodeOf(DioException err) => dioErrorCodeOf(err);
70	
71	  /// Pure decision function, independently testable: retry only if the
72	  /// error's code is one of the 6 allowlisted codes and the max-retries
73	  /// budget isn't exhausted yet.
74	  static bool shouldRetry(DioException err, int attempt) {
75	    final code = errorCodeOf(err);
76	    return code != null && retryableCodes.contains(code) && attempt < maxRetries;
77	  }
78	}

